_BASE_AGENT = _BASE_NS["agent"]
_OPERATOR = _OP_NS['sell_impact_reorder']
_OPERATOR_CONFIGURATION = {'sell_impact_demand_alpha': 0.25}

def _find_tape_hooks(namespace):
    seen = set()
    while isinstance(namespace, dict) and id(namespace) not in seen:
        seen.add(id(namespace))
        selector = namespace.get("_selected_tape")
        impl = namespace.get("_IMPL")
        if callable(selector) or impl is not None:
            return selector, impl
        namespace = namespace.get("_BASE_NS")
    return None, None

_PARENT_TAPE_SELECTOR, _PARENT_IMPL = _find_tape_hooks(_BASE_NS)

def _selected_tape(observation):
    if callable(_PARENT_TAPE_SELECTOR):
        return _PARENT_TAPE_SELECTOR(observation)
    if _PARENT_IMPL is None:
        return None
    try:
        player = int(observation.get("player", 0))
        step = int(observation.get("step", 0))
        native = _PARENT_IMPL.chassis.players[player]
        route = 2 if step >= 648 else native.get("route", 0)
        return SimpleNamespace(
            route_id=f"local-best-native-{route}",
            actions=tuple(_PARENT_IMPL.chassis.routes[route]),
        )
    except Exception:
        return None

def agent(observation, configuration=None):
    action = _BASE_AGENT(observation, configuration)
    tape = (_selected_tape(observation)
            if 'sell_impact_reorder' in {"market_queue_lockstep", "racegate_reservation",
                                  "opponent_front_run", "adaptive_market_tape_guard",
                                  "sale_advance", "sale_advance_policy",
                                  "sale_advance_pressure", "budget_guard",
                                  "room_guard", "supply_prefetch",
                                  "sell_impact_reorder"}
            else None)
    return _OPERATOR(observation, action, _OPERATOR_CONFIGURATION, tape)
# c358: compose Local Best's public market stack with V54's exact one-tile
# Productive Idle Workers opening.  Both source lineages and notices remain
# above.  This wrapper is original integration code by Taeyang/Codex, 2026.
import copy as _c358_copy

_C358_ENABLED = True
_C358_PARENT = agent
_C358_STATE = {}
_C358_REPORT = {}


def _c358_find_impl(namespace):
    seen = set()
    while isinstance(namespace, dict) and id(namespace) not in seen:
        seen.add(id(namespace))
        impl = namespace.get("_IMPL")
        if impl is not None:
            return impl
        namespace = namespace.get("_BASE_NS")
    return None


_C358_IMPL = _c358_find_impl(globals())
if _C358_ENABLED and _C358_IMPL is None:
    raise RuntimeError("c358 could not locate the native tape chassis")
_C358_RAW = (_c358_copy.deepcopy(_C358_IMPL.chassis.routes[0][:96])
             if _C358_IMPL is not None else None)


def _c358_install():
    tape = _C358_IMPL.chassis.routes[0]
    tape[:96] = _c358_copy.deepcopy(_C358_RAW)
    tape[0]["market"] = list(tape[0]["market"]) + [["BUY_SEED", "WHEAT", 1]]
    for step, command in {
        2: ["WEST"], 3: ["WEST"], 4: ["WEST"],
        5: ["PLANT", "WHEAT"], 6: ["WATER"],
    }.items():
        if tape[step]["hands"][1] != ["PASS"]:
            raise RuntimeError("c358 route-0 day-zero contract drift")
        tape[step]["hands"][1] = command
    if tape[29]["hands"][2] != ["BUILD_PASTURE"]:
        raise RuntimeError("c358 route-0 day-one contract drift")
    tape[29]["hands"][2] = ["WATER"]
    commands = [
        ["WEST"], ["WEST"], ["WEST"], ["WATER"], ["HARVEST"],
        ["BUILD_PASTURE"], ["EAST"], ["EAST"], ["DROP"],
    ]
    for step, command in zip(range(49, 58), commands):
        if tape[step]["hands"][0] != ["PASS"]:
            raise RuntimeError("c358 route-0 day-two contract drift")
        tape[step]["hands"][0] = command
    if max(len(action.get("market", [])) for action in tape[:96]) > 10:
        raise RuntimeError("c358 market order overflow")


def _c358_sell_extra(action, item, quantity):
    if quantity <= 0:
        return action
    orders = [list(order) for order in action.get("market", [])]
    sell = next((order for order in orders
                 if len(order) >= 3 and order[:2] == ["SELL", item]), None)
    if sell is not None:
        sell[2] += quantity
    elif len(orders) < 10:
        orders.append(["SELL", item, quantity])
    else:
        return action
    return dict(action, market=orders)


def agent(observation, configuration=None):
    seat = int(observation["player"])
    step = int(observation["step"])
    state = _C358_STATE.get(seat)
    if state is None or step <= state["step"]:
        if _C358_ENABLED:
            _c358_install()
        state = _C358_STATE[seat] = {"step": -1}
        _C358_REPORT.clear()
        _C358_REPORT.update(
            temporary_crop_seen=0, temporary_crop_harvested=0,
            restored_pasture_seen=0, delivered_extra_wheat=0,
            extension_errors=0,
        )
    action = _C358_PARENT(observation, configuration)
    if _C358_ENABLED:
        try:
            farm = observation["farms"][seat]
            private = observation["private"]
            site = farm["tiles"][4][2]
            if step == 6:
                _C358_REPORT["temporary_crop_seen"] = int(
                    isinstance(site, dict) and site.get("crop") == "WHEAT")
            if step == 54:
                _C358_REPORT["temporary_crop_harvested"] = int(
                    private["inventories"][1].get("WHEAT", 0))
            if step == 55:
                _C358_REPORT["restored_pasture_seen"] = int(
                    isinstance(site, dict) and site.get("kind") == "PASTURE")
            if (step == 57 and len(farm["hands"]) >= 1
                    and tuple(farm["hands"][0]) == (4, 4)
                    and action.get("hands", [[]])[0] == ["DROP"]):
                quantity = int(private["inventories"][1].get("WHEAT", 0))
                action = _c358_sell_extra(action, "WHEAT", quantity)
                _C358_REPORT["delivered_extra_wheat"] = quantity
        except Exception:
            _C358_REPORT["extension_errors"] += 1
    state["step"] = step
    return action


agent.telemetry = _C358_REPORT
kaggle_submission_agent = agent
# c365: preserve c358 and change only the existing CARROT2 controller's
# feed-reserve horizon from two days to one. Public One More Wheat, Metav4,
# V54 and Pipe16 use the same one-day horizon. Integration: Taeyang/Codex, 2026.
_C365_ENABLED = True
_C365_PARENT = agent
_C365_REPORT = {}


def _c365_find_carrot_namespace(namespace):
    seen = set()
    while isinstance(namespace, dict) and id(namespace) not in seen:
        seen.add(id(namespace))
        if "_CA_FEED_DAYS" in namespace and "_CA_REPORT" in namespace:
            return namespace
        namespace = namespace.get("_BASE_NS")
    return None


_C365_CA_NS = _c365_find_carrot_namespace(globals())
if _C365_CA_NS is None:
    raise RuntimeError("c365 could not locate the CARROT2 controller")
_C365_PARENT_FEED_DAYS = _C365_CA_NS["_CA_FEED_DAYS"]
if _C365_PARENT_FEED_DAYS != 2:
    raise RuntimeError("c365 parent feed-reserve contract drift")


def agent(observation, configuration=None):
    _C365_CA_NS["_CA_FEED_DAYS"] = 1 if _C365_ENABLED else _C365_PARENT_FEED_DAYS
    action = _C365_PARENT(observation, configuration)
    report = _C365_CA_NS.get("_CA_REPORT", {})
    _C365_REPORT.clear()
    _C365_REPORT.update(
        enabled=int(_C365_ENABLED),
        feed_days=int(_C365_CA_NS["_CA_FEED_DAYS"]),
        ca_swaps=int(report.get("ca_swaps", 0)),
        ca_feed_block=int(report.get("ca_feed_block", 0)),
        ca_errors=int(report.get("ca_errors", 0)),
    )
    return action


agent.telemetry = _C365_REPORT
kaggle_submission_agent = agent
c365_submission_agent = agent


# c368: preserve c365's production decisions and one-day feed horizon.
# Once its chassis has irrevocably entered terminal route 2, a reserve larger
# than ALL remaining wheat/carrot planting commands cannot be consumed.
# Include both crops for a conservative bound; do not predict future prices.
_C368_ON = True
_C368_PARENT = agent
_C368_REPORT = {}
_C368_OLD_BUFFER = _C365_CA_NS['_CA_BUFFER']
_C368_TAIL = _C365_CA_NS['_IMPL'].chassis.routes[2]
_C368_FUTURE = [0] * (len(_C368_TAIL) + 1)
for _c368_t in range(len(_C368_TAIL) - 1, -1, -1):
    _c368_a = _C368_TAIL[_c368_t]
    _c368_commands = [_c368_a.get('farmer') or ['PASS'], *_c368_a.get('hands', [])]
    _C368_FUTURE[_c368_t] = _C368_FUTURE[_c368_t + 1] + sum(
        c[:2] in (['PLANT', 'WHEAT'], ['PLANT', 'CARROT'])
        for c in _c368_commands)


def agent(observation, configuration=None):
    step = int(observation['step'])
    if step == 0:
        _C368_REPORT.clear()
        _C368_REPORT.update(enabled=int(_C368_ON), capped_turns=0,
                            current_reserve=_C368_OLD_BUFFER, ca_errors=0)
    reserve = _C368_OLD_BUFFER
    if _C368_ON and step >= 648:
        reserve = min(reserve, _C368_FUTURE[min(step + 1, len(_C368_TAIL))])
        _C368_REPORT['capped_turns'] += int(reserve < _C368_OLD_BUFFER)
    _C365_CA_NS['_CA_BUFFER'] = reserve
    try:
        action = _C368_PARENT(observation, configuration)
    finally:
        _C365_CA_NS['_CA_BUFFER'] = _C368_OLD_BUFFER
    _C368_REPORT['current_reserve'] = reserve
    _C368_REPORT['ca_errors'] = _C365_CA_NS['_CA_REPORT'].get('ca_errors', 0)
    return action


agent.telemetry = _C368_REPORT
kaggle_submission_agent = agent
c368_submission_agent = agent

# c369: shop-aware herd substitution from public V54 (Apache-2.0).
# Original layer: Seyit Kaan Gunes, kaggle.com/code/seyitkaangunes/kaggriculture-2820-score;
# V54 integration: Ahmed Berat Ozer, kaggle.com/code/ahmedberatozer/kaggriculture-v54-productive-wheat-and-patient.
# This isolated composition onto c368: Taeyang/Codex, 2026-09-21.
# Donor SHA: 5fbb75c9c40e6d9e26d95272ace47329b1ca319b3b2118232404de30806e7e9c. Its thresholds and purchase window are unchanged.
_C369_PARENT = agent
_C369_ENABLED = True
_Y_HOST = _C369_PARENT
projected_shed = _C365_CA_NS['projected_shed']
FarmView = _C365_CA_NS['FarmView']
_Y_CFG={'yarnsheep': True, 'yarngeese': True, 'days': (8, 11)}
import copy as _y_copy
_Y_PRODUCT={'COW':'MILK','SHEEP':'WOOL','GOOSE':'EGG'}
_Y_STRUCT={'COW':'PASTURE','SHEEP':'PASTURE','GOOSE':'COOP'}
_Y_COST={'COW':400,'SHEEP':500,'GOOSE':300}
_Y_SEED={'WHEAT':10,'CARROT':20,'TOMATO':50,'STRAWBERRY':100,'MELON':80}
_Y_STATES={}
_Y_REPORT={'swaps':0,'pick':0,'place':0,'harvest':0,'boost':0,'errors':0,'coop':0,'declined':0}

def _y_new_state():
    return {'last':-1,'pending':[],'credit':{},'sites':{},'sale':{},'coop_swap':0}

def _y_target(kind,shops,cfg):
    yarn='YARN_STORE' in shops
    egg=('BAKERY' in shops) or ('BRUNCH_SPOT' in shops)
    milk=sum(s in ('PIZZA_SHOP','ICE_CREAM_SHOP','SMOOTHIE_SHOP') for s in shops)
    if kind=='SHEEP' and cfg.get('nosheep') and not yarn and milk>=cfg.get('min_milk',0):return 'COW'
    if kind=='COW' and cfg.get('yarnsheep') and yarn:return 'SHEEP'
    if kind=='GOOSE' and cfg.get('nogeese') and not egg:return 'SHEEP' if yarn else 'COW'
    if kind=='GOOSE' and cfg.get('yarngeese') and yarn:return 'SHEEP'
    return None

def _y_fib(n):
    a,b=1,1
    for _ in range(n):a,b=b,a+b
    return a

def _y_cash(obs,action,market):
    farm=obs['farms'][int(obs['player'])];prices=obs['market']['prices'];shed=obs['private']['shed']
    try:shed=projected_shed({'farmer':action.get('farmer') or ['PASS'],'hands':action.get('hands') or [],'market':[]},FarmView(obs))
    except Exception:pass
    cash=float(farm['money']);cost=0.0;hires=int(farm.get('hires_today',0) or 0)
    quads=len(farm.get('unlocked_quadrants',[]) or [])
    for o in market:
        if not o:continue
        op=o[0]
        if op=='SELL' and len(o)>=3:
            cash+=0.8*min(max(0,int(o[2])),int(shed.get(o[1],0)))*float(prices.get(o[1],0))
        elif op=='BUY_ANIMAL' and len(o)>=3:cost+=int(o[2])*_Y_COST.get(o[1],500)
        elif op=='BUY_PRODUCT' and len(o)>=3:cost+=int(o[2])*(float(prices.get(o[1],0))+10)
        elif op=='BUY_SEED' and len(o)>=3:cost+=int(o[2])*_Y_SEED.get(o[1],100)
        elif op=='BUY_LAND':cost+=(1000,2000,4000)[min(2,max(0,quads-1))]
        elif op=='HIRE':cost+=_y_fib(hires);hires+=1
    return cash-cost

def _y_controller(obs,action,state,cfg):
    step=int(obs['step']);day=step//24;seat=int(obs['player'])
    farm=obs['farms'][seat];private=obs['private'];shed=private['shed'];inventories=private.get('inventories',[])
    shops=list((obs.get('town') or {}).get('unlocked_shops',[]) or [])
    tiles=farm['tiles'];n=len(tiles);center=n//2
    # 1. confirm last step's swapped purchases (physical shed gain)
    gained={}
    for p in state['pending']:
        to=p['to']
        if to not in gained:gained[to]=max(0,int(shed.get(to,0))-p['before'])
        got=min(p['qty'],gained[to]);gained[to]-=got
        if got>0:
            key=(p['from'],to);state['credit'][key]=state['credit'].get(key,0)+got
            if _Y_STRUCT[p['from']]!=_Y_STRUCT[to]:state['coop_swap']+=got
    state['pending']=[]
    result=_y_copy.deepcopy(action)
    market=result.get('market') or []
    result['market']=market
    # 2. purchase-point substitution by unlocked shops (cash-checked)
    if cfg['days'][0]<=day<=cfg['days'][1]:
        for o in market:
            if len(o)>=3 and o[0]=='BUY_ANIMAL' and o[1] in _Y_COST and 1<=int(o[2])<=cfg.get('maxq',2):
                to=_y_target(o[1],shops,cfg)
                if to is None or to==o[1]:continue
                trial=[list(x) if isinstance(x,list) else x for x in market]
                for t in trial:
                    if isinstance(t,list) and t==o:t[1]=to
                if _y_cash(obs,result,trial)<cfg.get('margin',100):
                    _Y_REPORT['declined']+=1;continue
                state['pending'].append({'from':o[1],'to':to,'qty':int(o[2]),'before':int(shed.get(to,0))})
                _Y_REPORT['swaps']+=int(o[2]);o[1]=to
    # 3. worker command rewrites (PICKUP / PLACE / BUILD_COOP) and harvest credit
    workers=[result.get('farmer') or ['PASS'],*(result.get('hands') or [])]
    positions=[farm['farmer'],*farm['hands']]
    avail={k:int(shed.get(k,0)) for k in _Y_COST}
    seen=set();occupied=set()
    for actor,work in enumerate(workers[:len(positions)]):
        if not work or not isinstance(work,list):continue
        inv=inventories[actor] if actor<len(inventories) else {}
        x,y=positions[actor];tile=tiles[y][x];site=(x,y);op=work[0]
        if op=='PICKUP' and len(work)>=2 and work[1] in _Y_COST:
            kind=work[1];qty=max(1,int(work[2])) if len(work)>2 else 1
            if avail.get(kind,0)>=qty:avail[kind]-=qty;continue
            if not (x in (center-1,center) and y in (center-1,center)):continue
            if any(inv.get(a,0) for a in _Y_COST):continue
            for (frm,to),c in list(state['credit'].items()):
                if frm==kind and c>=qty and avail.get(to,0)>=qty:
                    work[1]=to;state['credit'][(frm,to)]=c-qty;avail[to]-=qty;_Y_REPORT['pick']+=qty;break
        elif op=='PLACE' and len(work)>=2 and work[1] in _Y_COST:
            kind=work[1]
            if inv.get(kind,0)>0:continue
            for to in ('COW','SHEEP','GOOSE'):
                if (to!=kind and inv.get(to,0)>0 and isinstance(tile,dict) and tile.get('kind')==_Y_STRUCT[to]
                        and not tile.get('animal') and site not in occupied):
                    work[1]=to;state['sites'][site]=to;occupied.add(site);_Y_REPORT['place']+=1;break
        elif op=='BUILD_COOP' and state['coop_swap']>0:
            work[0]='BUILD_PASTURE';_Y_REPORT['coop']+=1
        elif op=='HARVEST' and site in state['sites'] and site not in seen:
            if isinstance(tile,dict) and tile.get('animal')==state['sites'][site]:
                units=max(0,int(tile.get('yield_units',0) or 0))
                if units:
                    prod=_Y_PRODUCT[tile['animal']];state['sale'][prod]=state['sale'].get(prod,0)+units;_Y_REPORT['harvest']+=units
            seen.add(site)
    result['farmer'],result['hands']=workers[0],workers[1:]
    # 4. sell the extra production at the tape's own existing sale slots (never add new orders)
    if cfg.get('boost',True):
        for prod,credit in list(state['sale'].items()):
            credit=min(credit,int(shed.get(prod,0)))
            state['sale'][prod]=credit
            if credit<=0:continue
            planned=sum(max(0,int(o[2])) for o in market if len(o)>=3 and o[0]=='SELL' and o[1]==prod)
            if planned<=0:continue
            extra=min(credit,int(shed.get(prod,0))-planned)
            if extra<=0:continue
            for o in market:
                if len(o)>=3 and o[0]=='SELL' and o[1]==prod and int(o[2])>0:
                    o[2]=int(o[2])+extra;state['sale'][prod]=credit-extra;_Y_REPORT['boost']+=extra;break
    return result

def _y_agent_shopherd(observation,configuration=None):
    action=_Y_HOST(observation,configuration)
    try:
        seat=int(observation['player']);step=int(observation['step'])
        state=_Y_STATES.get(seat)
        if state is None or step<=state['last']:state=_Y_STATES[seat]=_y_new_state()
        state['last']=step
        return _y_controller(observation,action,state,_Y_CFG)
    except Exception:
        _Y_REPORT['errors']+=1
        return action



def agent(observation, configuration=None):
    if int(observation['step']) == 0:
        for key in _Y_REPORT:
            _Y_REPORT[key] = 0
    if _C369_ENABLED:
        return _y_agent_shopherd(observation, configuration)
    return _C369_PARENT(observation, configuration)

agent.telemetry = _Y_REPORT
kaggle_submission_agent = agent
c369_submission_agent = agent

