# c387: public More Wheat, Smarter Sales (Dmitrii Gluzdov, Apache-2.0).
# https://www.kaggle.com/code/dmitriigluzdov/kaggriculture-more-wheat-smarter-sales
# Exact donor 83fb106f37fcc10f3c3d9db8a78ded1529da30e9e232976ec0cf46fd6662fed4; retain notices. Integration Taeyang/Codex 2026-09-23.
# Only near-best forecast trajectories plus diagnostic counters are transferred.
# Keep the inherited cadence, stock limits, products, library and physical plan.
_C387_ENABLED = True
_C387_PARENT = agent
_C387_TELEMETRY = {}
if _C387_ENABLED:
    if _C365_CA_NS['_v92_p_forecast'].__globals__ is not _C365_CA_NS:
        raise RuntimeError('c387 forecast namespace drift')
    exec(compile('def _v92_p_forecast(obs, st):\n    step = int(obs["step"])\n    shops = tuple(obs["town"]["unlocked_shops"][:2])\n    cands = _v92_p_pair(shops)\n    if _V92_EP is not None:\n        cands = [c for c in cands if c[0] % 2 != _V92_EP % 2]\n    seen = st["obs"]\n    lo = step - 240\n    scored = []\n    recent = [(tt, i) for (tt, i) in seen if tt >= lo]\n    for ep, ev in cands:\n        m = f = 0\n        for (tt, i), q in ev.items():\n            if lo <= tt < step - 1:\n                if (tt, i) in seen or (tt - 1, i) in seen or (tt + 1, i) in seen:\n                    m += 1\n                else:\n                    f += 1\n        miss = sum(1 for (tt, i) in recent if (tt, i) not in ev and (tt - 1, i) not in ev and (tt + 1, i) not in ev)\n        scored.append((m - 0.5 * f - 0.5 * miss, ev))\n    scored.sort(key=lambda x: -x[0])\n    # The event-match score is coarse (half-point increments). Preserve up to\n    # three positively supported, near-best trajectories instead of treating a\n    # one-point lead as certainty about the rival\'s next sale.\n    if not scored or scored[0][0] < 0:\n        return [ev for _, ev in scored[:_V92_P_TOP]]\n    frontier = [ev for score, ev in scored[:3] if score >= scored[0][0] - 1.0]\n    return frontier\n\ndef _v92_predict(obs, action, st):\n    step = int(obs["step"])\n    _v92_p_update(obs, st)\n    if step < 150 or step >= 700:\n        return action\n    if step % _V92_P_EVERY == 0 or "best" not in st:\n        st["best"] = _v92_p_forecast(obs, st)\n    best = st["best"]\n    if not best:\n        return action\n    native = _IMPL.chassis.players.get(int(obs["player"]))\n    if not native or native.get("route") not in _IMPL.chassis.routes:\n        return action\n    tape = _IMPL.chassis.routes[native["route"]]\n    market = [list(o) for o in action.get("market") or []]\n    already = {o[1] for o in market if len(o) > 1 and o[0] in ("SELL", "BUY_PRODUCT")}\n    stock = projected_shed(action, FarmView(obs))\n    changed = False\n    for i, item in enumerate(_V92_P_ITEMS):\n        if item not in _V92_P_USE or item in already or len(market) >= MAX_ORDERS:\n            continue\n        votes = sum(1 for ev in best if ev.get((step + 1, i), 0) + ev.get((step + 2, i), 0) >= _V92_P_K)\n        if votes < 1:\n            continue\n        alternate = not (best[0].get((step + 1, i), 0) + best[0].get((step + 2, i), 0) >= _V92_P_K)\n        ours = 0\n        for t in range(step + 1, min(len(tape), step + _V92_P_H + 1)):\n            ours += sum(min(100, int(o[2])) for o in (tape[t] or {}).get("market") or []\n                        if len(o) >= 3 and o[0] == "SELL" and o[1] == item)\n        qty = min(int(stock.get(item, 0)), ours)\n        if qty > 0:\n            market.insert(0, ["SELL", item, qty])\n            _V92_P_REPORT["pred_units"] += qty\n            _V92_P_REPORT["pred_fires"] += 1\n            if alternate:\n                _V92_P_REPORT["frontier_fires"] = _V92_P_REPORT.get("frontier_fires", 0) + 1\n                _V92_P_REPORT["frontier_units"] = _V92_P_REPORT.get("frontier_units", 0) + qty\n            changed = True\n    if not changed:\n        return action\n    result = dict(action)\n    result["market"] = market[:MAX_ORDERS]\n    return result\n', '<c387-public-forecast-frontier>', 'exec'), _C365_CA_NS)

def agent(observation, configuration=None):
    if int(observation['step']) == 0 and _C387_ENABLED:
        for key in _C365_CA_NS['_V92_P_REPORT']:
            _C365_CA_NS['_V92_P_REPORT'][key] = 0
    action = _C387_PARENT(observation, configuration)
    _C387_TELEMETRY.clear()
    _C387_TELEMETRY.update(_C386_TELEMETRY)
    if _C387_ENABLED:
        _C387_TELEMETRY.update({'c387_'+k:v for k,v in _C365_CA_NS['_V92_P_REPORT'].items()})
    return action

agent.telemetry = _C387_TELEMETRY
c387_submission_agent = agent

